method pluck(arr: seq<int>) returns (res: seq<int>)
    requires |arr| <= 10000
    requires forall i :: 0 <= i < |arr| ==> arr[i] >= 0
    ensures res == [] || (|res| == 2 && res[0] >= 0 && res[1] >= 0 && res[1] < |arr| && 
                          forall j :: 0 <= j < |arr| && arr[j] % 2 == 0 ==> 
                          (arr[j] > res[0] || (arr[j] == res[0] && j > res[1])))
{
    var minVal := int.MaxValue;
    var minIndex := -1;
    var foundEven := false;

    // Iterate through the array to find the smallest even value and its index
    var i := 0;
    while i < |arr|
        invariant 0 <= i <= |arr|
        invariant foundEven ==> minIndex >= 0 && minIndex < i
    {
        if arr[i] % 2 == 0 {
            if !foundEven || arr[i] < minVal || (arr[i] == minVal && i < minIndex) {
                minVal := arr[i];
                minIndex := i;
                foundEven := true;
            }
        }
        i := i + 1;
    }

    if foundEven {
        res := [minVal, minIndex];
    } else {
        res := [];
    }
}
